import { cleanupOutdatedCaches, precacheAndRoute, createHandlerBoundToURL } from 'workbox-precaching';
import { NavigationRoute, registerRoute } from 'workbox-routing';

// Precache all assets generated by Vite build
cleanupOutdatedCaches();
precacheAndRoute(self.__WB_MANIFEST || []);

// SPA Navigation Fallback, ignoring /api calls and backend routes
try {
  const handler = createHandlerBoundToURL('/index.html');
  const navigationRoute = new NavigationRoute(handler, {
    denylist: [/^\/api/],
  });
  registerRoute(navigationRoute);
} catch (e) {
  // Silent fallback if index.html is not in manifest in dev mode
}

// Ensure updated service worker activates immediately
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

/**
 * Handle incoming Web Push notifications from server
 */
self.addEventListener('push', (event) => {
  let payload = {};

  if (event.data) {
    try {
      payload = event.data.json();
    } catch (err) {
      payload = {
        title: '⏰ OrganizeUp Reminder',
        body: event.data.text(),
      };
    }
  }

  const title = payload.title || '⏰ OrganizeUp Reminder';
  const body = payload.body || 'You have a scheduled reminder ready for review.';
  const url = payload.url || (payload.data && payload.data.url) || '/captures';
  const tag = payload.tag || 'organizeup-reminder';

  const notificationOptions = {
    body,
    icon: payload.icon || '/pwa-192x192.png',
    badge: payload.badge || '/organizeup-favicon.svg',
    tag,
    renotify: true,
    requireInteraction: true,
    data: {
      url,
      tag,
      timestamp: Date.now(),
      ...(payload.data || {}),
    },
  };

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      const isAppFocused = clientList.some((client) => client.focused);

      // Broadcast push event to all connected window clients (for in-app badge / toast updates)
      clientList.forEach((client) => {
        client.postMessage({
          type: 'PUSH_NOTIFICATION_RECEIVED',
          payload: { title, body, url, tag, data: payload.data },
          isAppFocused,
        });
      });

      // Avoid double OS notification if the user is currently actively focused in the app
      if (isAppFocused) {
        return;
      }

      return self.registration.showNotification(title, notificationOptions);
    })
  );
});

/**
 * Handle user click on push notification
 */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  const targetUrl = event.notification.data?.url || '/';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      // If a tab is already open, focus it and navigate
      for (const client of clientList) {
        if ('focus' in client) {
          client.focus();
          if ('navigate' in client && targetUrl) {
            return client.navigate(targetUrl);
          }
          return client;
        }
      }

      // If no window is open, open a new browser window
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl);
      }
    })
  );
});

